<script setup lang="ts">
import { computed, onMounted, ref } from 'vue';
import { useRoute, useRouter } from 'vue-router';
import type { ActionRecommendation, SupportIntent } from '@goodnight/shared-types';
import { api } from '../api';

type Snapshot = { confidence: string; domain?: string; subDomain?: string; eventType?: string; stage?: string; contextTags: string[]; peopleContext: string[]; decisionContext: string[]; behaviorSignals: string[]; recoverySignals: string[]; facts: string[]; feelings: string[]; needs: string[]; constraints: string[]; risks: string[]; intensity?: number; urgency?: number };
type Detail = { journey: { id: string; title: string; domain: string; stage: string; status: string; currentIntent?: SupportIntent; summary?: string }; snapshot: Snapshot | null; updates: Array<{ id: string; kind: string; content: string; createdAt: string }>; commitments: Array<{ id: string; title: string; description?: string; status: string }> };

const route = useRoute(); const router = useRouter(); const detail = ref<Detail | null>(null); const updateContent = ref(''); const busy = ref(false); const intentBusy = ref(false); const planBusy = ref(false); const error = ref(''); const routeMessage = ref(''); const selectedIntent = ref<SupportIntent | ''>(''); const actionTitle = ref(''); const actionDescription = ref(''); const recommendation = ref<ActionRecommendation | null>(null); const graduation = ref<{ message: string; initialIntensity?: number; latestIntensity?: number; completedActions: number; followUps: number } | null>(null); const experienceDraft = ref<{ id: string; title: string; content: string; retrospective?: string } | null>(null); const graduationMessage = ref('');
const intents: Array<{ value: SupportIntent; label: string; detail: string }> = [{ value: 'JUST_LISTEN', label: '先听我说完', detail: '不急着给办法，先把事情放在这里。' }, { value: 'FIND_PEOPLE', label: '看看同路的人', detail: '只看已同意公开的后来经历。' }, { value: 'SEE_OUTCOMES', label: '看看后来怎么样', detail: '先看相似经历的结果和转折。' }, { value: 'NEXT_STEP', label: '找一个下一步', detail: '把行动缩小到今晚做得完。' }, { value: 'STOP_IMPULSE', label: '先缓一缓', detail: '把冲动放进决定保险箱。' }, { value: 'PREPARE_CONVERSATION', label: '准备一次沟通', detail: '整理想对现实中的人说的话。' }, { value: 'NOTHING_NOW', label: '今天先不处理', detail: '暂停也可以，稍后从今晚入口回来。' }, { value: 'HIGH_DISTRESS', label: '我现在很危险', detail: '先连接现实中的可信任支持。' }];
const canConfirm = computed(() => Boolean(detail.value?.snapshot && detail.value.snapshot.confidence !== 'user_confirmed'));
const wait = (milliseconds: number) => new Promise((resolve) => window.setTimeout(resolve, milliseconds));

async function load() { const id = String(route.query.id ?? ''); if (!id) { error.value = '缺少旅程编号'; return; } try { detail.value = (await api.get<{ item: Detail }>(`/api/v1/journeys/${id}`)).item; } catch (cause) { error.value = cause instanceof Error ? cause.message : '旅程加载失败'; } }
async function confirm() { if (!detail.value?.snapshot) return; busy.value = true; error.value = ''; try { await api.patch(`/api/v1/journeys/${detail.value.journey.id}/situation`, detail.value.snapshot); await load(); } catch (cause) { error.value = cause instanceof Error ? cause.message : '确认失败'; } finally { busy.value = false; } }
async function chooseIntent() { if (!detail.value || !selectedIntent.value) return; intentBusy.value = true; error.value = ''; try { const response = await api.patch<{ route: { targetRoute: string; message: string } }>(`/api/v1/journeys/${detail.value.journey.id}/intent`, { intent: selectedIntent.value }); routeMessage.value = response.route.message; const target = response.route.targetRoute; if (target === '/pages/journey/detail') await load(); else await router.push(target.includes('?') ? `${target}&journeyId=${detail.value.journey.id}` : `${target}?journeyId=${detail.value.journey.id}`); } catch (cause) { error.value = cause instanceof Error ? cause.message : '支持方向保存失败'; } finally { intentBusy.value = false; } }
async function addAction() { if (!detail.value || !actionTitle.value.trim()) return; busy.value = true; try { await api.post(`/api/v1/journeys/${detail.value.journey.id}/actions`, { title: actionTitle.value, description: actionDescription.value }); actionTitle.value = ''; actionDescription.value = ''; await load(); } catch (cause) { error.value = cause instanceof Error ? cause.message : '行动创建失败'; } finally { busy.value = false; } }
async function requestRecommendation() { if (!detail.value) return; planBusy.value = true; error.value = ''; recommendation.value = null; try { const queued = await api.post<{ job: { id: string } }>(`/api/v1/journeys/${detail.value.journey.id}/action-plan`, { content: detail.value.snapshot?.facts.join('；') }); for (let attempt = 0; attempt < 24; attempt += 1) { await wait(400); const task = await api.get<{ status: string; result?: string; structured?: Record<string, unknown> }>(`/api/v1/ai/tasks/${queued.job.id}`); if (['succeeded', 'fallback', 'failed'].includes(task.status)) { if (task.status === 'failed') throw new Error('推荐暂时不可用，请先自己写下一步'); const structured = task.structured ?? {}; recommendation.value = { title: typeof structured.title === 'string' ? structured.title : '', why: typeof structured.why === 'string' ? structured.why : undefined, description: typeof structured.description === 'string' ? structured.description : task.result, completionDefinition: typeof structured.completionDefinition === 'string' ? structured.completionDefinition : undefined, difficulty: structured.difficulty === 'tiny' || structured.difficulty === 'easy' || structured.difficulty === 'moderate' ? structured.difficulty : undefined, expectedDuration: typeof structured.expectedDuration === 'string' ? structured.expectedDuration : undefined, dueInDays: typeof structured.dueInDays === 'number' ? structured.dueInDays : 1 }; break; } } if (!recommendation.value?.title) throw new Error('推荐没有形成可确认的行动，请自己写下一步'); } catch (cause) { error.value = cause instanceof Error ? cause.message : '行动推荐失败'; } finally { planBusy.value = false; } }
async function acceptRecommendation() { if (!detail.value || !recommendation.value?.title.trim()) return; busy.value = true; try { await api.post(`/api/v1/journeys/${detail.value.journey.id}/actions`, { title: recommendation.value.title, description: recommendation.value.completionDefinition || recommendation.value.description, dueAt: new Date(Date.now() + Math.max(1, recommendation.value.dueInDays ?? 1) * 86_400_000).toISOString() }); recommendation.value = null; await load(); } catch (cause) { error.value = cause instanceof Error ? cause.message : '推荐行动保存失败'; } finally { busy.value = false; } }
async function addUpdate() { if (!detail.value || !updateContent.value.trim()) return; busy.value = true; try { await api.post(`/api/v1/journeys/${detail.value.journey.id}/updates`, { content: updateContent.value, kind: 'later' }); updateContent.value = ''; await load(); } catch (cause) { error.value = cause instanceof Error ? cause.message : '进展保存失败'; } finally { busy.value = false; } }
async function graduate() { if (!detail.value) return; busy.value = true; try { const response = await api.post<any>(`/api/v1/journeys/${detail.value.journey.id}/graduate`); graduation.value = response.graduation; await load(); } catch (cause) { error.value = cause instanceof Error ? cause.message : '暂时还不能结束旅程'; } finally { busy.value = false; } }
async function chooseGraduation(decision: 'willing' | 'later' | 'no') { if (!detail.value) return; busy.value = true; try { const response = await api.post<any>(`/api/v1/journeys/${detail.value.journey.id}/graduation-consent`, { decision }); graduation.value = response.graduation; experienceDraft.value = response.draft; graduationMessage.value = decision === 'willing' ? '草稿已生成，编辑并确认后会进入管理员审核。' : decision === 'later' ? '已记住你的选择，这段经历不会公开。' : '这段经历不会进入同路网络。'; } catch (cause) { error.value = cause instanceof Error ? cause.message : '分享选择保存失败'; } finally { busy.value = false; } }
async function saveExperienceDraft() { if (!experienceDraft.value) return; busy.value = true; try { const response = await api.patch<any>(`/api/v1/peer-experiences/${experienceDraft.value.id}`, { title: experienceDraft.value.title, content: experienceDraft.value.content, retrospective: experienceDraft.value.retrospective }); experienceDraft.value = response.item; graduationMessage.value = '已确认并提交管理员审核，公开前仍会经过人工审核。'; } catch (cause) { error.value = cause instanceof Error ? cause.message : '经历草稿保存失败'; } finally { busy.value = false; } }
onMounted(load);
</script>

<template>
  <section class="page goodnight-page modern-page">
    <header class="detail-head"><button class="back" aria-label="返回" @click="router.back()">‹</button><span class="section-kicker">正在整理</span><h1>{{ detail?.journey?.title || '旅程详情' }}</h1><p>{{ detail?.journey?.domain }} · {{ detail?.journey?.stage }}</p></header><p v-if="error" class="error-text" role="alert">{{ error }}</p>
    <template v-if="detail">
      <section class="modern-card snapshot-card"><div class="card-heading"><div><span class="section-kicker">经历指纹</span><h2>我理解的是这些，对吗？</h2></div><span class="stage-badge">{{ detail.snapshot?.confidence === 'agent_draft' ? '等你确认' : '已确认' }}</span></div><p class="intro">这些内容来自你的原话和真实记录。确认前，它们只是一份整理草稿；确认后，才会用于下一步建议和同路匹配。</p><div v-if="detail.snapshot" class="snapshot-grid"><div><b>事情</b><span v-for="item in detail.snapshot.facts" :key="`fact-${item}`">{{ item }}</span></div><div><b>感受</b><span v-for="item in detail.snapshot.feelings" :key="`feeling-${item}`">{{ item }}</span><span v-if="!detail.snapshot.feelings.length">还没有写下</span></div><div><b>在意的需要</b><span v-for="item in detail.snapshot.needs" :key="`need-${item}`">{{ item }}</span><span v-if="!detail.snapshot.needs.length">还没有写下</span></div><div><b>眼前的限制</b><span v-for="item in detail.snapshot.constraints" :key="`constraint-${item}`">{{ item }}</span><span v-if="!detail.snapshot.constraints.length">还没有写下</span></div><div v-if="detail.snapshot.peopleContext.length"><b>涉及的人</b><span v-for="item in detail.snapshot.peopleContext" :key="`person-${item}`">{{ item }}</span></div><div v-if="detail.snapshot.contextTags.length"><b>这件事的线索</b><span class="tag-list"><i v-for="item in detail.snapshot.contextTags" :key="`tag-${item}`">{{ item }}</i></span></div></div><button v-if="canConfirm" class="primary-button" :disabled="busy" @click="confirm">这些内容准确，继续</button><p v-else class="confirmed-note">已按你的确认保存。你可以随时在后续进展里补充变化。</p></section>
      <section v-if="detail.snapshot?.confidence === 'user_confirmed'" class="modern-card intent-card"><div class="card-heading"><div><span class="section-kicker">下一步由你选择</span><h2>你现在更需要哪一种支持？</h2></div><span v-if="detail.journey.currentIntent" class="stage-badge">已选择</span></div><div class="intent-list"><button v-for="item in intents" :key="item.value" type="button" :class="{ selected: selectedIntent === item.value || detail.journey.currentIntent === item.value }" @click="selectedIntent = item.value"><strong>{{ item.label }}</strong><small>{{ item.detail }}</small></button></div><button class="primary-button" :disabled="intentBusy || !selectedIntent" @click="chooseIntent">保存我的选择</button><p v-if="routeMessage" class="route-message">{{ routeMessage }}</p></section>
      <section v-if="detail.journey.currentIntent === 'NEXT_STEP' || detail.journey.stage === 'planning' || detail.journey.stage === 'acting'" class="modern-card"><div class="card-heading"><div><span class="section-kicker">只推荐一个主动作</span><h2>今晚，只做这一件事</h2></div><span>{{ detail.commitments.length }} 条已记录</span></div><p class="intro">推荐来自你已确认的经历和当前支持方向。先看清楚，再由你确认；系统不会自动替你承诺。</p><button v-if="!recommendation" class="outline-button full" :disabled="planBusy" @click="requestRecommendation">{{ planBusy ? '正在整理一个现实动作...' : '给我一个可确认的建议' }}</button><div v-if="recommendation" class="recommendation-card"><h3>{{ recommendation.title }}</h3><p v-if="recommendation.why">为什么：{{ recommendation.why }}</p><p v-if="recommendation.completionDefinition || recommendation.description">完成标准：{{ recommendation.completionDefinition || recommendation.description }}</p><small v-if="recommendation.expectedDuration">预计 {{ recommendation.expectedDuration }}</small><div class="checkin-actions"><button class="secondary-small" :disabled="busy || planBusy" @click="recommendation = null">这件事不适合我</button><button class="primary-small" :disabled="busy" @click="acceptRecommendation">我愿意试试</button></div></div><div class="action-form"><input v-model="actionTitle" placeholder="也可以自己写一件小事" /><input v-model="actionDescription" placeholder="怎样算完成？（可选）" /><button class="primary-button" :disabled="busy" @click="addAction">保存这一步</button></div><div v-for="action in detail.commitments" :key="action.id" class="timeline-row"><span :class="['dot', action.status]" /><div><strong>{{ action.title }}</strong><small>{{ action.status === 'completed' ? '已完成' : action.status === 'paused' ? '等待调整' : '等待行动' }}</small></div></div></section>
      <section class="modern-card"><div class="card-heading"><h2>后来呢</h2><span class="section-kicker">真实进展</span></div><textarea v-model="updateContent" maxlength="1000" placeholder="记录事情后来发生了什么，或这一步带来了什么变化" /><div class="counter">{{ updateContent.length }}/1000</div><button class="outline-button full" :disabled="busy || !updateContent.trim()" @click="addUpdate">保存进展</button></section><section class="modern-card"><h2>时间线</h2><div v-for="update in detail.updates" :key="update.id" class="timeline-row"><span class="dot" /><div><strong>{{ update.kind === 'later' ? '后来呢' : update.kind === 'created' ? '开始整理' : '行动记录' }}</strong><small>{{ update.content }}</small></div></div><p v-if="!detail.updates.length" class="empty-note">写下第一条进展后，这里会留下真实记录。</p></section><button v-if="detail.journey.status === 'active'" class="graduate-button" :disabled="busy" @click="graduate">完成这段旅程</button>
      <section v-if="graduation" class="modern-card graduation-card"><h2>{{ graduation.message }}</h2><div class="graduation-metrics"><span>最初强度 <b>{{ graduation.initialIntensity ?? '未记录' }}</b></span><span>最近强度 <b>{{ graduation.latestIntensity ?? '未记录' }}</b></span><span>完成行动 <b>{{ graduation.completedActions }}</b></span><span>回访次数 <b>{{ graduation.followUps }}</b></span></div><p>愿意把这段经历匿名留给下一位正在经历类似事情的人吗？</p><div class="graduation-actions"><button :disabled="busy" @click="chooseGraduation('willing')">愿意</button><button :disabled="busy" @click="chooseGraduation('later')">以后再说</button><button :disabled="busy" @click="chooseGraduation('no')">不分享</button></div><p v-if="graduationMessage" class="confirmed-note">{{ graduationMessage }}</p><div v-if="experienceDraft" class="draft-editor"><label>给这段经历起个名字<input v-model="experienceDraft.title" maxlength="100" /></label><label>你愿意留下的内容<textarea v-model="experienceDraft.content" maxlength="1600" /></label><label>现在回头看<textarea v-model="experienceDraft.retrospective" maxlength="1000" /></label><button class="primary-button" :disabled="busy" @click="saveExperienceDraft">确认并提交审核</button></div></section>
    </template>
  </section>
</template>

<style scoped>
.modern-page { display: grid; gap: 16px; padding: 0 14px 150px; }.detail-head { padding: 28px 10px 14px; }.back { display: block; margin-bottom: 24px; border: 0; background: transparent; color: var(--gn-green-dark); font-size: 36px; cursor: pointer; }.detail-head h1 { margin: 6px 0; color: var(--gn-green-dark); font-family: var(--gn-font-display); font-size: 34px; line-height: 1.25; }.detail-head p { margin: 0; color: var(--gn-subtext); }.modern-card { border: 1px solid var(--gn-border); border-radius: var(--gn-radius-card); background: var(--gn-card); box-shadow: var(--gn-shadow-card); padding: 22px; }.modern-card h2 { margin: 0; color: var(--gn-text); font-size: 21px; }.card-heading { display: flex; justify-content: space-between; align-items: start; gap: 10px; }.stage-badge { flex: 0 0 auto; padding: 6px 10px; border-radius: 99px; background: var(--gn-green-light); color: var(--gn-green-dark); font-size: 12px; }.intro, .confirmed-note { color: var(--gn-subtext); line-height: 1.7; }.snapshot-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 12px; margin-top: 18px; }.snapshot-grid > div { display: grid; gap: 7px; padding: 12px; border-radius: 16px; background: #fbfaf3; }.snapshot-grid b { color: var(--gn-green-dark); font-size: 13px; }.snapshot-grid span { color: var(--gn-subtext); font-size: 13px; line-height: 1.5; }.tag-list { display: flex; flex-wrap: wrap; gap: 6px; }.tag-list i { border-radius: 999px; background: var(--gn-green-light); padding: 4px 7px; font-style: normal; }.primary-button, .outline-button, .graduate-button { border: 0; border-radius: 15px; padding: 12px; font: inherit; cursor: pointer; }.primary-button { width: 100%; margin-top: 18px; background: var(--gn-green); color: #fff; }.primary-button:disabled { opacity: .55; cursor: wait; }.outline-button { background: transparent; border: 1px solid var(--gn-border); color: var(--gn-green-dark); }.full { width: 100%; margin-top: 18px; }.intent-list { display: grid; grid-template-columns: 1fr 1fr; gap: 9px; margin-top: 18px; }.intent-list button { display: grid; gap: 4px; min-height: 72px; border: 1px solid var(--gn-border); border-radius: 16px; padding: 12px; background: #fffdf8; color: var(--gn-text); text-align: left; font: inherit; cursor: pointer; }.intent-list button.selected { border-color: var(--gn-green); background: var(--gn-green-light); box-shadow: inset 0 0 0 1px var(--gn-green); }.intent-list small { color: var(--gn-subtext); line-height: 1.4; }.route-message { margin-bottom: 0; color: var(--gn-green-dark); }.action-form { display: grid; gap: 8px; margin-top: 18px; }.action-form input, textarea { width: 100%; box-sizing: border-box; border: 1px solid var(--gn-border); border-radius: 14px; padding: 12px; background: #fffdf8; font: inherit; }.modern-card textarea { min-height: 110px; resize: none; line-height: 1.6; }.counter { margin-top: 5px; color: var(--gn-subtext); font-size: 12px; text-align: right; }.timeline-row { display: flex; gap: 12px; margin-top: 16px; }.dot { flex: 0 0 10px; width: 10px; height: 10px; margin-top: 6px; border-radius: 50%; background: #c7d8b5; }.dot.completed { background: var(--gn-green); }.timeline-row strong, .timeline-row small { display: block; }.timeline-row small { margin-top: 4px; color: var(--gn-subtext); line-height: 1.5; }.graduate-button { width: 100%; background: var(--gn-green-dark); color: #fff; }.empty-note { color: var(--gn-subtext); }.error-text { margin: 0 4px; color: var(--gn-danger); }.graduation-card h2 { color: var(--gn-green-dark); line-height: 1.45; }.graduation-metrics { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 8px; margin: 18px 0; }.graduation-metrics span { display: grid; gap: 5px; min-width: 0; padding: 10px 8px; border-right: 1px solid var(--gn-border); color: var(--gn-subtext); font-size: 12px; text-align: center; }.graduation-metrics span:last-child { border-right: 0; }.graduation-metrics b { color: var(--gn-green-dark); font-size: 20px; }.graduation-actions { display: flex; flex-wrap: wrap; gap: 8px; }.graduation-actions button { flex: 1 1 100px; min-height: 44px; border: 1px solid var(--gn-border); border-radius: 14px; background: #fffdf8; color: var(--gn-green-dark); font: inherit; cursor: pointer; }.graduation-actions button:first-child { border-color: var(--gn-green); background: var(--gn-green); color: #fff; }.draft-editor { display: grid; gap: 10px; margin-top: 16px; padding-top: 16px; border-top: 1px solid var(--gn-border); }.draft-editor label { display: grid; gap: 6px; color: var(--gn-green-dark); font-size: 13px; }.draft-editor input, .draft-editor textarea { width: 100%; box-sizing: border-box; border: 1px solid var(--gn-border); border-radius: 14px; padding: 11px; background: #fffdf8; font: inherit; line-height: 1.6; }.draft-editor textarea { min-height: 110px; resize: none; }
@media (max-width: 430px) { .modern-page { padding-inline: 10px; }.modern-card { padding: 18px; }.detail-head h1 { font-size: 29px; }.snapshot-grid, .intent-list { grid-template-columns: 1fr; }.graduation-metrics { grid-template-columns: repeat(2, minmax(0, 1fr)); }.graduation-metrics span:nth-child(2) { border-right: 0; } }
 .recommendation-card { margin-top: 16px; padding: 15px; border: 1px solid rgba(95,127,62,.3); border-radius: 18px; background: var(--gn-green-light); }
 .recommendation-card h3 { margin: 0; color: var(--gn-green-dark); font-size: 18px; }
 .recommendation-card p { margin: 8px 0 0; font-size: 13px; }
 .recommendation-card small { display: block; margin-top: 8px; color: var(--gn-subtext); }
</style>
